    # Find the separator lattice; separators are full rows/columns of the
    # background divider color, with four-cell panels between them.
    sep_color = max(set(v for row in grid for v in row), key=lambda v: sum(x == v for row in grid for x in row))
    sep_rows = [r for r in range(h) if all(v == sep_color for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]
    r_starts = [0] + [r + 1 for r in sep_rows if r + 1 < h]
    c_starts = [0] + [c + 1 for c in sep_cols if c + 1 < w]
    # Each panel's interior is the four-cell block before its following separator.
    panel_h = min([r - a for a, r in zip(r_starts, sep_rows)] + [h - r_starts[-1]])
    panel_w = min([c - a for a, c in zip(c_starts, sep_cols)] + [w - c_starts[-1]])
    panel_h = min(panel_h, 4)
    panel_w = min(panel_w, 4)

    # The special, non-key panel contains the stencil to project. It is the
    # densest occupied panel outside the leftmost key column.
    stencil = None
    best = -1
    for r0 in r_starts:
        for c0 in c_starts[1:]:
            cells = {(dr, dc) for dr in range(panel_h) for dc in range(panel_w)
                     if grid[r0 + dr][c0 + dc] not in (0, sep_color)}
            if len(cells) > best:
                best, stencil = len(cells), cells
    if not stencil:
