    h, w = len(grid), len(grid[0])
    # The lattice separators are the uniform full rows and columns.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    if not sep_rows or not sep_cols:
        raise ValueError('expected full separator rows and columns')
    sep_color = grid[sep_rows[0]][0]
    if any(grid[r][0] != sep_color for r in sep_rows) or any(grid[0][c] != sep_color for c in sep_cols):
        # Determine the color shared by all separators if top/left cells aren't separators.
        colors = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}
        sep_color = max(colors, key=lambda v: sum(x == v for row in grid for x in row))
    r_bounds = [-1] + sep_rows + [h]
    c_bounds = [-1] + sep_cols + [w]
    r_spans = [(a + 1, b) for a, b in zip(r_bounds, r_bounds[1:])]
    c_spans = [(a + 1, b) for a, b in zip(c_bounds, c_bounds[1:])]
    ph = max(b - a for a, b in r_spans)
    pw = max(b - a for a, b in c_spans)
    if any(b - a != ph for a, b in r_spans) or any(b - a != pw for a, b in c_spans):
        raise ValueError('unequal panel sizes')

    # Locate the occupied stencil panel outside the leftmost key column.
    candidates = []
    for ri, (r0, r1) in enumerate(r_spans):
        for ci, (c0, c1) in enumerate(c_spans[1:], start=1):
            cells = {(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] not in (0, sep_color)}
            if cells:
                candidates.append((len(cells), cells))
    if not candidates:
        raise ValueError('no stencil found')
    stencil = max(candidates, key=lambda x: x[0])[1]

    out = [row[:] for row in grid]
    for r0, r1 in r_spans:
        key_colors = {grid[r][c] for r in range(r0, r1) for c in range(c_spans[0][0], c_spans[0][1])
                      if grid[r][c] not in (0, sep_color)}
        if not key_colors:
            continue
        color = min(key_colors)
        for c0, c1 in c_spans:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = color if (r-r0, c-c0) in stencil else 0
    return out

